const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
 ['理事長有什麼權力','第18條'],['理事長可以一個人決定事情嗎','不是理事長一個人'],['理事長的職權是什麼','章程'],
 ['理事長可以代表協會簽約嗎','沒有明文'],['理事長能不能幫協會簽合約','沒有明文'],
 ['理事長做錯事會怎樣','第22條'],['理監事要負法律責任嗎','第58條'],['理事違反章程會怎樣','罷免'],
 ['理事的工作是什麼','親自出席'],['理事要做什麼','第18條'],['理事有什麼責任','第31條'],['常務理事要做什麼','三分之一'],
 ['理事長生病不能做事怎麼辦','章程'],['理事長出國誰代理','代理'],['理事長開刀住院這段時間誰負責','章程'],
 ['顧問要開會員大會通過嗎','沒有規定'],['可以請顧問嗎','看章程'],['名譽理事長可以設嗎','沒有條文'],['名譽理事長要不要經過選舉','不是法定的理事'],
 ['顧問可以領錢嗎','沒有明文'],['名譽理事長可以領車馬費嗎','第19條'],
 ['名譽理事長有投票權嗎','第16條'],['顧問可以在理事會投票嗎','列席'],
 ['理事長的太太可以當監事嗎','沒有限制親屬'],['理事長的兒子可以當理事嗎','沒有限制親屬'],
 ['監事可以阻止理事會決議嗎','糾正意見'],['監事發現有問題要怎麼辦','提報會員'],
 ['理事長怎麼被罷免','三分之一'],['理事長要怎麼罷免','答辯'],['想罷免理事長可以嗎','第29條'],
['名譽理事長要選嗎','不是法定的理事'],['理事長沒經過大會同意借錢給協會可以嗎','沒有明文'],['理事長先幫協會墊錢可以嗎','第11條'],['總幹事跟理事長誰比較大','身分不一樣'],['秘書長和理事長誰管誰','選任職員'],
];
const no=['合作社理事長有什麼權力','公會理事長做錯事會怎樣','合作社理事的工作是什麼','理事長挪用公款怎麼辦','監事可以查帳嗎','理事長可以領薪水嗎','理事可以請辭嗎','理事長過世怎麼辦','理事長可以不經過理事會就花錢嗎','直選的理事長被罷免之後還是理事嗎','理事長怎麼選','理事任期幾年','理事長印章誰保管','公會顧問可以領錢嗎','工作人員要負什麼責任','理事長請假可以嗎','協會借錢給理事長可以嗎','協會借錢給會員要怎麼辦','合作社總幹事跟理事主席誰大'];
